-- ============================================================================
-- sszctop 维度排序说明同步脚本
-- 来源：职业认知——谁是职场TOP 介绍.docx 各维度解释部分的职业说明。
-- 说明：仅更新排序说明，不修改维度、职业、正确名次及其它模块数据；可重复执行。
-- ============================================================================
SET NAMES utf8mb4;
-- 维度：微信步数（steps）
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='常年奔波于田间地头、种植基地、农户庭院和乡镇农技站，需要实地察看作物长势、指导病虫害防治，有时一天走访多个村庄。户外工作、步行距离长、步数极其可观，日均通常在 15000 步以上，稳居第一。',r.update_time=NOW() WHERE d.code='steps' AND c.name='农业技术推广员';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='全天带队穿梭于各个展厅，一边行走一边讲解，每场讲解持续数十分钟，日复一日。工作时间内几乎不存在坐下休息的时间，相当于室内“巡馆式”行走。日均步数常达 12000—15000 步，堪比导游。',r.update_time=NOW() WHERE d.code='steps' AND c.name='博物馆讲解员';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='外勤记者需要赶赴现场、追拍画面、采访不同对象，时常辗转于城市各处甚至外出远郊，步数累积迅速。即使后期需伏案写稿，但出外勤时的行走强度拉高了整体均值。日均步数一般约 10000—12000 步。',r.update_time=NOW() WHERE d.code='steps' AND c.name='新闻记者';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='病房医生查房、会诊、前往各科室处理病情，住院医师更是整日在病区、护士站、检验科之间折返；虽然门诊医生相对久坐，但大量住院部与急诊医生的高强度走动使整体均值处于较高水平，日均 8000—11000 步。',r.update_time=NOW() WHERE d.code='steps' AND c.name='临床医生';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='课堂内来回巡视、板书讲解，课间穿梭于教室和办公室，班主任还需跑操、带队放学等。虽不是持续高强度，但站立和行走贯穿全天，几乎没有“久坐不动”的时段，日均步数多在 7000—9000 步。',r.update_time=NOW() WHERE d.code='steps' AND c.name='中小学教师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='管理工作需巡视办公区、生产车间或门店，也要频繁进出会议室、接待客户、出差考察。但因会议和案头工作占一定比重，整体行走量不如前五者。日均约 6000—8000 步，视行业有所浮动。',r.update_time=NOW() WHERE d.code='steps' AND c.name='企业经理';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='诉讼律师需要往返法院、看守所或客户单位，调查取证时也有较多室外行走；但非诉和事务性律师有大量卷宗研读、文书起草等久坐时间，整体平均行走量被拉低。日均步数大致在 5000—7000 步。',r.update_time=NOW() WHERE d.code='steps' AND c.name='律师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='此处指机关办公室从事综合协调、文秘会务、政策研究的公务员，以室内办公为主，多数时间在工位、会议室、打印机之间短距离移动。虽然偶有外勤，但久坐特征明显，日均步数约 4000—6000 步。',r.update_time=NOW() WHERE d.code='steps' AND c.name='综合管理类公务员';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='主要面对屏幕处理数据、撰写报告、参加策略会，工作形态以久坐研究为核心，走动通常只发生在午餐、去洗手间或短时会议间隙。日均步数普遍较低，约 3000—4500 步。',r.update_time=NOW() WHERE d.code='steps' AND c.name='金融分析师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='典型的技术研发岗位，长时间面对电脑编码、训练模型、调试算法，开会也多以线上或坐下来完成。由于任务高度沉浸，主动起身次数很少，日均步数一般 2500—4000 步。',r.update_time=NOW() WHERE d.code='steps' AND c.name='人工智能工程师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='同样以取数、建模、制作报表和跨部门沟通为主，沟通大多通过即时通讯或会议室小范围移动完成，行走场景极为有限。和人工智能工程师相近，整体日均步数在 2500—3500 步左右，有时甚至更低。',r.update_time=NOW() WHERE d.code='steps' AND c.name='数据分析师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='从构思草图到细节调色，全程绑定于电脑前，需要长时间连续专注，连续数小时不挪位很常见。哪怕去接水、上卫生间的频次都容易被压缩，是典型的“久坐不动型”职业，日均步数通常在 2000—3000 步，为12个职业中最低。',r.update_time=NOW() WHERE d.code='steps' AND c.name='视觉设计师';
-- 维度：工作时长（hours）
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='（这里主要指卖方分析师、投行分析师等）以“每周100小时”的极端工时著称，项目期连轴转、通宵赶材料是常态，平均每周工时可达80小时以上，远超其他职业，稳居第一。',r.update_time=NOW() WHERE d.code='hours' AND c.name='金融分析师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='查房、手术、夜班、病历文书层层叠加，住院医师阶段更是长期超负荷，日均工作12小时常见，周均工时普遍在60—80小时，工作量极为饱和。',r.update_time=NOW() WHERE d.code='hours' AND c.name='临床医生';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='诉讼与非诉律师均面临严苛的计费工时与多重截止日压力，调查取证、开庭准备、合同审核经常挤占休息时间，周均工时多在55—70小时。',r.update_time=NOW() WHERE d.code='hours' AND c.name='律师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='突发报道和深度调查要求全天候响应，截稿压力下日夜兼程是家常便饭，每日工作时长常超10小时，周均约50—65小时，且时间高度碎片化。',r.update_time=NOW() WHERE d.code='hours' AND c.name='新闻记者';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='互联网与科技行业“996”乃至更长的研发周期较为普遍，赶版本、调模型时加班密集，周均工时普遍在50—60小时，部分企业可达70小时以上。',r.update_time=NOW() WHERE d.code='hours' AND c.name='人工智能工程师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='中高层管理者会议密集、决策链长、业绩责任重，隐形工作时间（差旅、应酬、思考型加班）很多，日均工作常超10小时，周均约50—60小时。',r.update_time=NOW() WHERE d.code='hours' AND c.name='企业经理';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='日常教学仅冰山一角，备课、批改、学生管理、家校沟通等“隐形工作”大量挤占业余时间，学期内早出晚归，日均工作9—10小时，周均45—55小时。',r.update_time=NOW() WHERE d.code='hours' AND c.name='中小学教师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='业务需求频繁变动，取数、建模、报表需快速响应，项目冲刺期加班是常态，但整体强度略低于前端研发，周均工时约45—50小时。',r.update_time=NOW() WHERE d.code='hours' AND c.name='数据分析师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='乙方与互联网设计岗位常为需求反复修改、多轮评审买单，赶稿期连续熬夜，但因项目间隙有缓冲，整体周均工时约45小时左右。',r.update_time=NOW() WHERE d.code='hours' AND c.name='视觉设计师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='以机关办公室工作为主，大多数岗位遵循标准工时，虽偶有迎检、会议筹备等加班，但总体工作时间规律，周均约40—45小时。',r.update_time=NOW() WHERE d.code='hours' AND c.name='综合管理类公务员';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='田间指导虽需奔波，但多依农时和天气安排，作业时间较有弹性，无重大灾情或项目时基本维持正常下班，周均约40小时。',r.update_time=NOW() WHERE d.code='hours' AND c.name='农业技术推广员';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='严格按开闭馆时间和排班表运行，每场讲解时长固定，闭馆即结束工作，几乎不存在加班，周均工时约35—40小时，为12个职业中最短。',r.update_time=NOW() WHERE d.code='hours' AND c.name='博物馆讲解员';
-- 维度：压力指数（pressure）
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='直接面对生命安危，诊断与治疗容错率极低；长期超负荷运转，夜班扰乱生理节律；同时承受科研、晋升与医患关系多重挤压，压力指数稳居首位。',r.update_time=NOW() WHERE d.code='pressure' AND c.name='临床医生';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='市场瞬息万变，报告精准度直接关联巨额资金决策；极端的时效压迫与业绩排名，配合几乎全年无休的高强度运转，精神长期处于高压敏锐状态。',r.update_time=NOW() WHERE d.code='pressure' AND c.name='金融分析师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='诉讼胜负、交易成败往往取决于细节与时限，客户预期严苛且后果不可逆；计费工时的束缚与持续的知识更新，共同构成重度职业焦虑。',r.update_time=NOW() WHERE d.code='pressure' AND c.name='律师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='截稿时效与事实准确性的双重博弈，深度报道常伴人身风险与法律边界试探；信息的不确定性、持续在线的抢独家状态，令神经难以放松。',r.update_time=NOW() WHERE d.code='pressure' AND c.name='新闻记者';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='背负明确的业绩指标与团队存续责任，决策后果直接且迅速反馈；市场竞争、人际冲突与随时待命的隐形消耗，形成持续性的综合压力。',r.update_time=NOW() WHERE d.code='pressure' AND c.name='企业经理';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='技术迭代飞快，模型性能与项目交付存在硬性指标；高强度脑力输出叠加行业“优化”焦虑，使得长期处于技术竞跑与不确定性压力之中。',r.update_time=NOW() WHERE d.code='pressure' AND c.name='人工智能工程师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='学生安全责任如山，成绩提升与社会期待构成双向负担；隐形工作时长与家校矛盾调和，致使情绪劳动强度居高不下。',r.update_time=NOW() WHERE d.code='pressure' AND c.name='中小学教师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='数据准确性与时效性关系业务决策，需求频繁变动易形成“被动应答”的压迫感；技术保鲜与价值证明的压力持续并存。',r.update_time=NOW() WHERE d.code='pressure' AND c.name='数据分析师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='流程规范严密、问责体系清晰，层级协调与程序合规带来审慎压力；突发任务与迎检考核使心理紧绷，但整体波动较缓。',r.update_time=NOW() WHERE d.code='pressure' AND c.name='综合管理类公务员';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='创意主观评判反复迭代，修改无常易引发自我怀疑；交稿节点的累积式突击，带来阶段性高压，但无直接安全或重大经济损失风险。',r.update_time=NOW() WHERE d.code='pressure' AND c.name='视觉设计师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='工作对象依赖自然条件，成果反馈周期长且影响因子分散；指导责任虽有，但节奏可调、弹性较大，整体压力较为和缓。',r.update_time=NOW() WHERE d.code='pressure' AND c.name='农业技术推广员';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='工作内容固定、环境稳定，讲解任务按固定排班与脚本执行；无硬性指标考核与即时风险，心理负荷在12个职业中最轻。',r.update_time=NOW() WHERE d.code='pressure' AND c.name='博物馆讲解员';
-- 维度：技能门槛（skill）
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='培养周期最长，需完成5-8年本硕博教育、3年住院医师规范化培训及终身继续教育；执业医师资格通过率严格，知识体系横跨基础医学与临床实践，技能累积曲线极为陡峭，门槛稳居首位。',r.update_time=NOW() WHERE d.code='skill' AND c.name='临床医生';
