UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='工程师群体位列“年度出差最多人群”首位。需出差支持系统部署、客户培训或异地项目开发。单次出差约10-15天，跨国项目差旅频率更高，部分岗位年累计出差可达7个月。',r.update_time=NOW() WHERE d.code='travel' AND c.name='人工智能工程师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='职业特性决定必须为客户的异地案件奔走。非诉律师比诉讼律师年均出差更多。出差天数分化明显，虽多数在30天以内，但业务广泛的律师年均飞行可达80-90次。',r.update_time=NOW() WHERE d.code='travel' AND c.name='律师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='常规岗位需坚守病房，但资深专家和高年资医生因异地会诊（多点执业）、全国性或国际学术研讨而常有差旅，属于高级别专业交流为主的低频但高质量出行。',r.update_time=NOW() WHERE d.code='travel' AND c.name='临床医生';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='涉及客户现场驻场搭建数据系统的岗位有较高出差需求（如单次驻场1-2个月），但多数总部支持岗无需出差。因项目性质不同，该职业整体出差分化较大。',r.update_time=NOW() WHERE d.code='travel' AND c.name='数据分析师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='以办公室创作为主。会展设计、品牌活动策划等岗位有现场勘察和跟活动需求，会存在偶发的短途、集中出差，但整体非工作常态。',r.update_time=NOW() WHERE d.code='travel' AND c.name='视觉设计师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='除审计、纪委等特殊岗位和参加异地培训外，多数岗位坐班为主，工作地稳定。层级间有差异，但机关整体的平均出差频率在职业光谱中处于低位。',r.update_time=NOW() WHERE d.code='travel' AND c.name='综合管理类公务员';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='工作高度围绕固定校历和课堂，外出多限于短期培训、教研交流或带领学生比赛。虽有校领导及中层岗位出差可能性高，但占大比例的一线教师年均出差频率较低。',r.update_time=NOW() WHERE d.code='travel' AND c.name='中小学教师';
UPDATE gkzh_sszctop_dimension_rank r JOIN gkzh_sszctop_dimension d ON d.dimension_id=r.dimension_id JOIN gkzh_sszctop_career c ON c.career_id=r.career_id SET r.description='工作固定性最强，仅在博物馆展厅内活动。除极少的外出讲解比赛或馆际借展交流，工作无需出差，频率为12个职业中最低',r.update_time=NOW() WHERE d.code='travel' AND c.name='博物馆讲解员';
